//! Write a fixture whose terms and field names collide with `Object.prototype`.
//!
//! JavaScript dictionaries inherit from `Object.prototype`, so assigning to a
//! key like `__proto__` through a normal object resolves to the inherited
//! accessor instead of creating an own property. The term vanishes from the
//! serialized `matches` map and `Object.keys` comes back empty, which also loses
//! the highlight for that term.
//!
//! A JSON fixture generated by `mkfixture` cannot express this: the corpus has
//! to contain a literal `__proto__` token, and the *field name* has to be
//! `__proto__` as well to cover `matches.term.__proto__`. So this writes the
//! index directly.
//!
//! Usage: `mkhostile <output.marz>`

use std::sync::Arc;

use marz_core::languages::registry;
use marz_core::{IndexBuilder, Language};

fn main() {
    let output = std::env::args()
        .nth(1)
        .expect("usage: mkhostile <output.marz>");
    let language: Arc<dyn Language> = registry::resolve("en").language;

    let mut builder = IndexBuilder::new(language);
    // Field names are validated like query syntax, so `__proto__` is legal:
    // no separator, no operator, no slash.
    builder
        .ref_field("location")
        .field("__proto__", 1.0)
        .field("body", 1.0);

    // Both the term and the field name collide with `Object.prototype`.
    builder.add("collide", 1.0, |name| match name {
        "__proto__" => Some("__proto__ term in a colliding field".to_string()),
        "body" => Some("__proto__ and constructor and toString".to_string()),
        _ => None,
    });
    // A control: an ordinary document, so a test can tell "the map is empty" from
    // "the whole search is broken".
    builder.add("plain", 1.0, |name| match name {
        "__proto__" => None,
        "body" => Some("ordinary text with keyboard".to_string()),
        _ => None,
    });

    let index = builder.build();
    let bytes = index.to_binary(true).unwrap();
    std::fs::write(&output, &bytes).expect("write fixture");
    eprintln!(
        "{} docs, {} terms, {} bytes -> {output}",
        index.document_count(),
        index.term_count(),
        bytes.len()
    );
}
